
/* VLM_CORS_PROXY_V2_WORKER_BEGIN */
const VLM_CORS_PROXY_V2_RAW_INDEX_URL = "https://raw.githubusercontent.com/gamer14457/viciouslom-updates/c4b8c2ad5952/update/indexVL.web.admin.js";

function vlmCorsHeadersV2(extra){
  const h = new Headers(extra || {});
  h.set("access-control-allow-origin", "*");
  h.set("access-control-allow-methods", "GET,POST,OPTIONS");
  h.set("access-control-allow-headers", "*");
  h.set("access-control-expose-headers", "*");
  h.set("x-vlm-cors-proxy", "V2");
  return h;
}

function vlmCorsBootScriptV2(){
  return `
;(()=>{try{
  if(window.__VLM_CORS_PROXY_V2__) return;
  window.__VLM_CORS_PROXY_V2__=1;
  const MARK='[VLM_CORS_PROXY_V2]';
  const HOSTS=/^https:\\/\\/(api|api-bak)\\.joynetgame\\.com\\//i;
  function mapUrl(u){
    try{
      if(!u) return u;
      const s=String(u);
      if(!HOSTS.test(s)) return u;
      return '/vlm-cors-proxy?u='+encodeURIComponent(s);
    }catch(e){return u}
  }

  const oldFetch=window.fetch;
  if(typeof oldFetch==='function'){
    window.fetch=function(input,init){
      try{
        if(typeof input==='string'){
          const m=mapUrl(input);
          if(m!==input) input=m;
        }else if(input && input.url){
          const m=mapUrl(input.url);
          if(m!==input.url) input=new Request(m,input);
        }
      }catch(e){}
      return oldFetch.call(this,input,init);
    };
  }

  const XHR=window.XMLHttpRequest;
  if(XHR && XHR.prototype && XHR.prototype.open){
    const oldOpen=XHR.prototype.open;
    XHR.prototype.open=function(method,url){
      try{
        const m=mapUrl(url);
        if(m!==url) arguments[1]=m;
      }catch(e){}
      return oldOpen.apply(this,arguments);
    };
  }

  console.warn(MARK,'installed');
}catch(e){try{console.warn('[VLM_CORS_PROXY_V2] install error',e)}catch(_){}}})();
`;
}



function vlmAssetTimeoutScriptV6(){
  return `
;(()=>{try{
  if(window.__VLM_ASSET_TIMEOUT_V6__) return;
  window.__VLM_ASSET_TIMEOUT_V6__=1;

  const MARK='[VLM_ASSET_TIMEOUT_V6]';
  const RE=/\\/assets\\/(bundle-firstload-res|bundle-res|bundle-LoadingView)\\//i;

  const XHR=window.XMLHttpRequest;
  if(XHR && XHR.prototype && XHR.prototype.open && XHR.prototype.send){
    const oldOpen=XHR.prototype.open;
    const oldSend=XHR.prototype.send;

    XHR.prototype.open=function(method,url){
      try{ this.__vlm_asset_timeout_url=String(url||''); }catch(e){}
      return oldOpen.apply(this,arguments);
    };

    XHR.prototype.send=function(body){
      try{
        const u=String(this.__vlm_asset_timeout_url||'');
        if(RE.test(u)){
          if(!this.timeout || this.timeout < 180000) this.timeout = 180000;
          console.warn(MARK,'XHR asset timeout=',this.timeout,u);
        }
      }catch(e){}
      return oldSend.apply(this,arguments);
    };
  }

  try{
    if(window.cc && cc.assetManager && cc.assetManager.downloader){
      cc.assetManager.downloader.maxConcurrency = Math.max(cc.assetManager.downloader.maxConcurrency || 6, 8);
      cc.assetManager.downloader.maxRequestsPerFrame = Math.max(cc.assetManager.downloader.maxRequestsPerFrame || 6, 8);
    }
  }catch(e){}

  console.warn(MARK,'installed');
}catch(e){try{console.warn('[VLM_ASSET_TIMEOUT_V6] install error',e)}catch(_){}}})();
`;
}


/* VLM_PANEL_KEY_BRIDGE_V7_BEGIN */
function vlmCookieValueV7(req,name){
  try{
    const raw = req.headers.get("cookie") || "";
    const parts = raw.split(";");
    for(const part of parts){
      const i = part.indexOf("=");
      if(i < 0) continue;
      const k = part.slice(0,i).trim();
      const v = part.slice(i+1).trim();
      if(k === name) return decodeURIComponent(v);
    }
  }catch(e){}
  return "";
}

function vlmNormalizePanelKeyV7(k){
  return String(k || "").trim().replace(/^(key\s*=\s*)+/i,"").trim();
}

function vlmPanelKeyBridgeScriptV7(req){
  const key = vlmNormalizePanelKeyV7(vlmCookieValueV7(req,"vlm_key"));
  const safeKey = JSON.stringify(key);

  return `
;(()=>{try{
  if(window.__VLM_PANEL_KEY_BRIDGE_V7__) return;
  window.__VLM_PANEL_KEY_BRIDGE_V7__=1;

  const K=${safeKey};
  if(K){
    try{ localStorage.setItem("vlm_web_key", K); }catch(e){}
    try{ localStorage.setItem("vlm_pending_key", K); }catch(e){}
    try{ sessionStorage.setItem("vlm_web_key", K); }catch(e){}
    try{ window.__VLM_PANEL_KEY = K; }catch(e){}
    console.warn("[VLM_PANEL_KEY_BRIDGE_V7] installed keyPresent=1");
  }else{
    console.warn("[VLM_PANEL_KEY_BRIDGE_V7] installed keyPresent=0");
  }
}catch(e){try{console.warn("[VLM_PANEL_KEY_BRIDGE_V7] error",e)}catch(_){}}})();
`;
}
/* VLM_PANEL_KEY_BRIDGE_V7_END */


async function vlmCorsIndexRespV2(req){
  /* VLM_PANEL_KEY_BRIDGE_V7_INDEX_NOSTORE */
  const hasPanelKey = vlmNormalizePanelKeyV7(vlmCookieValueV7(req,"vlm_key")) ? "1" : "0";

  const r = await fetch(VLM_CORS_PROXY_V2_RAW_INDEX_URL, {
    headers: { "cache-control": "no-cache" },
    cf: {
      cacheEverything: true,
      cacheTtl: 86400
    }
  });

  if(!r.ok){
    return new Response("index fetch failed: "+r.status, {
      status: 502,
      headers: vlmCorsHeadersV2({"content-type":"text/plain; charset=utf-8"})
    });
  }

  const body =
    vlmPanelKeyBridgeScriptV7(req) + "\n" +
    vlmCorsBootScriptV2() + "\n" +
    vlmAssetTimeoutScriptV6() + "\n" +
    await r.text();

  return new Response(body, {
    status: 200,
    headers: {
      "content-type": "application/javascript; charset=utf-8",
      "cache-control": "no-store",
      "access-control-allow-origin": "*",
      "x-vlm-panel-key-bridge": "V7",
      "x-vlm-panel-key-present": hasPanelKey,
      "x-vlm-index-cors-proxy": "V2",
      "x-vlm-index-cache": "NO_STORE_V7",
      "x-vlm-topfire-style-cache": "INDEX_V7"
    }
  });
}



async function vlmCorsProxyRespV2(req,u){
  if(req.method === "OPTIONS"){
    return new Response(null, { status: 204, headers: vlmCorsHeadersV2() });
  }

  const targetRaw = u.searchParams.get("u") || "";
  let target;
  try{
    target = new URL(targetRaw);
  }catch(e){
    return new Response(JSON.stringify({ok:false,message:"BAD_URL"}), {
      status: 400,
      headers: vlmCorsHeadersV2({"content-type":"application/json"})
    });
  }

  if(!/^(api|api-bak)\.joynetgame\.com$/i.test(target.hostname)){
    return new Response(JSON.stringify({ok:false,message:"HOST_NOT_ALLOWED"}), {
      status: 403,
      headers: vlmCorsHeadersV2({"content-type":"application/json"})
    });
  }

  const headers = new Headers(req.headers);
  headers.delete("host");
  headers.delete("origin");
  headers.delete("referer");
  headers.delete("cookie");

  const init = {
    method: req.method,
    headers,
    redirect: "follow"
  };

  if(req.method !== "GET" && req.method !== "HEAD"){
    init.body = req.body;
  }

  let rr;
  try{
    rr = await fetch(target.toString(), init);
  }catch(e){
    return new Response(JSON.stringify({ok:false,message:"UPSTREAM_ERROR",detail:String(e && e.message || e)}), {
      status: 502,
      headers: vlmCorsHeadersV2({"content-type":"application/json"})
    });
  }

  const out = vlmCorsHeadersV2(rr.headers);
  out.set("cache-control", "no-store");
  out.set("x-vlm-cors-target", target.hostname);

  return new Response(rr.body, {
    status: rr.status,
    statusText: rr.statusText,
    headers: out
  });
}
