const PWA_HEAD=`<link rel="manifest" href="/app-manifest.json"><meta name="apple-mobile-web-app-capable" content="yes"><meta name="mobile-web-app-capable" content="yes"><meta name="apple-mobile-web-app-status-bar-style" content="black-translucent"><meta name="apple-mobile-web-app-title" content="Legend of Mushroom"><link rel="apple-touch-icon" href="/icon.png">`;


// ===== VLM_ASSET_BYPASS_V4 =====
// Assets grandes/estáticos do jogo não precisam passar pelo relay do Worker.
// A origem/CDN já responde com CORS liberado para esses bin/json/manifest.
// Isso reduz timeout no WebView/Cocos em bundle-firstload-res e bundles pesados.

async function vlmAssetBypassResp(req,u){
  /* VLM_TOPFIRE_STYLE_CACHE_V5_ASSET_PROXY */
  const p = u.pathname || "";
  const ok =
    /^\/assets\/bundle-firstload-res\/native\//.test(p) ||
    /^\/assets\/bundle-res\/native\//.test(p) ||
    /^\/assets\/bundle-res\/config\.[A-Za-z0-9]+\.json$/.test(p) ||
    /^\/assets\/bundle-LoadingView\/native\//.test(p);

  if(!ok) return null;
  if(req.method !== "GET" && req.method !== "HEAD") return null;

  const target = "https://lom.joynetgame.com" + p + (u.search || "");
  const cache = caches.default;
  const cacheKey = new Request("https://vlm-admin-cache.local" + p + (u.search || ""), { method: "GET" });

  if(req.method === "GET"){
    const cached = await cache.match(cacheKey);
    if(cached){
      const h = new Headers(cached.headers);
      h.set("access-control-allow-origin", "*");
      h.set("access-control-allow-methods", "GET,HEAD,OPTIONS");
      h.set("access-control-allow-headers", "*");
      h.set("cross-origin-resource-policy", "cross-origin");
      h.set("x-vlm-topfire-style-cache", "HIT_V5");
      h.set("x-vlm-asset-proxy", "V5");
      return new Response(cached.body, {
        status: cached.status,
        statusText: cached.statusText,
        headers: h
      });
    }
  }

  let rr;
  try{
    rr = await fetch(target, {
      method: req.method,
      redirect: "follow",
      cf: {
        cacheEverything: true,
        cacheTtl: 604800
      }
    });
  }catch(e){
    return new Response("VLM_ASSET_PROXY_V5_UPSTREAM_ERROR: " + String(e && e.message || e), {
      status: 502,
      headers: {
        "content-type": "text/plain; charset=utf-8",
        "cache-control": "no-store",
        "access-control-allow-origin": "*",
        "x-vlm-asset-proxy": "V5_ERROR"
      }
    });
  }

  const h = new Headers(rr.headers);
  h.set("access-control-allow-origin", "*");
  h.set("access-control-allow-methods", "GET,HEAD,OPTIONS");
  h.set("access-control-allow-headers", "*");
  h.set("cross-origin-resource-policy", "cross-origin");
  h.set("cache-control", rr.ok ? "public, max-age=604800, immutable" : "no-store");
  h.set("x-vlm-topfire-style-cache", "MISS_V5");
  h.set("x-vlm-asset-proxy", "V5");
  h.delete("set-cookie");

  const resp = new Response(rr.body, {
    status: rr.status,
    statusText: rr.statusText,
    headers: h
  });

  if(req.method === "GET" && rr.ok){
    try{
      await cache.put(cacheKey, resp.clone());
    }catch(e){}
  }

  return resp;
}


const __VLM_V7_ORIGINAL_DEFAULT__ = {
  async fetch(req,env){
    const u=new URL(req.url);

  if(u.pathname==="/vlm-cors-proxy") return vlmCorsProxyRespV2(req,u);
  if(u.pathname==="/assets/script/index.9c819.js") return vlmCorsIndexRespV2(req);

    const vlmBypass = await vlmAssetBypassResp(req,u);
    if(vlmBypass)return vlmBypass;
    if(u.pathname==="/")return panel(req,u);
    if(u.pathname==="/app-manifest.json")return manifestResp();
    if(u.pathname==="/icon.png")return iconResp();
    if(u.pathname==="/reset")return reset();
    if(u.pathname==="/vlm-web-activate")return webActivate(req,env);
    if(u.pathname==="/vlm-web-verify")return webVerify(req,env);
    if(u.pathname==="/vlm-web-login")return webLogin(req,env);
    if(u.pathname==="/play")return play(req,u,env);
    return proxy(req,u,env);
  }
};

function norm(v){
  v=String(v||"").trim();
  if(/^key=/i.test(v))v=v.replace(/^key=/i,"").trim();
  return v.toUpperCase();
}

function cookie(req,n){
  let c=req.headers.get("cookie")||"";
  let m=c.match(new RegExp("(?:^|; )"+n+"=([^;]*)"));
  return m?decodeURIComponent(m[1]):"";
}

function headersHtmlRawVlmSecurity(){
  return new Headers({"content-type":"text/html;charset=UTF-8","cache-control":"no-store","x-vlm-worker-clean":"no-auto-clean"});
}

function headersHtml(){
  const h=headersHtmlRawVlmSecurity.apply(null,arguments);
  try{
    h.set("content-security-policy","default-src 'self' https: data: blob:; script-src 'self' 'unsafe-inline' 'unsafe-eval' https: blob:; style-src 'self' 'unsafe-inline' https:; img-src 'self' https: data: blob:; connect-src 'self' https: wss:; media-src 'self' https: data: blob:; worker-src 'self' blob:; manifest-src 'self'; base-uri 'self'; frame-ancestors 'none'");
    h.set("referrer-policy","no-referrer");
    h.set("x-content-type-options","nosniff");
    h.set("permissions-policy","camera=(),microphone=(),geolocation=()");
  }catch(_){}
  return h;
}


// Remove o manifest do jogo e injeta o MEU + meta tags da Apple no <head>.
function injectPwa(html){
  html=html.replace(/<link[^>]+rel=["']?manifest["']?[^>]*>/gi,"");
  if(/<head[^>]*>/i.test(html)){
    html=html.replace(/<head[^>]*>/i,m=>m+PWA_HEAD);
  }else{
    html=PWA_HEAD+html;
  }
  return html;
}

function manifestResp(){
  return new Response(JSON.stringify(MANIFEST),{
    headers:{"content-type":"application/manifest+json;charset=UTF-8","cache-control":"no-store","access-control-allow-origin":"*","x-vlm-worker-clean":"no-auto-clean"}
  });
}


const ICON_PNG_BASE64="";

function base64ToBytes(b64){
  const bin=atob(b64);
  const out=new Uint8Array(bin.length);
  for(let i=0;i<bin.length;i++)out[i]=bin.charCodeAt(i);
  return out;
}

async function iconResp(){
  const h=new Headers();
  h.set("content-type","image/png");
  h.set("cache-control","public,max-age=86400");
  h.set("x-vlm-worker-clean","no-auto-clean");
  return new Response(base64ToBytes(ICON_PNG_BASE64),{status:200,headers:h});
}


// ===== RATE LIMITING (binding nativo do Cloudflare) =====
// Protege os endpoints sensíveis por IP. Fail-open: se o binding não estiver
// configurado ou der erro, NÃO bloqueia (não derruba acesso legítimo).
async function rateLimited(env,req,bucket){
  try{
    if(!env || !env.RL)return false;
    const ip=req.headers.get("CF-Connecting-IP")||req.headers.get("x-forwarded-for")||"unknown";
    const {success}=await env.RL.limit({key:ip+":"+bucket});
    return !success;
  }catch(e){
    return false;
  }
}

function tooManyJson(){
  return new Response(JSON.stringify({ok:false,message:"RATE LIMIT - AGUARDE ALGUNS SEGUNDOS"}),{
    status:429,
    headers:{"content-type":"application/json;charset=UTF-8","cache-control":"no-store","retry-after":"30","x-vlm-worker-clean":"no-auto-clean"}
  });
}

function tooManyHtml(){
  const h=headersHtml();
  h.set("retry-after","30");
  return new Response(panelHtml(false,"MUITAS TENTATIVAS - AGUARDE UNS SEGUNDOS"),{status:429,headers:h});
}

function clearCookies(h){
  h.append("set-cookie","vlm_key=; Path=/; Max-Age=0; Secure; HttpOnly; SameSite=Lax");
  h.append("set-cookie","vlm_session=; Path=/; Max-Age=0; Secure; HttpOnly; SameSite=Lax");
}

function saveCookies(h,key,session){
  h.append("set-cookie","vlm_key="+encodeURIComponent(key)+"; Path=/; Max-Age=2592000; Secure; HttpOnly; SameSite=Lax");
  h.append("set-cookie","vlm_session="+encodeURIComponent(session)+"; Path=/; Max-Age=1200; Secure; HttpOnly; SameSite=Lax");
}

function panelResp(saved,msg,h){
  return new Response(panelHtml(saved,msg),{headers:h||headersHtml()});
}



function headersJson(){
  const h=new Headers();
  h.set("content-type","application/json;charset=UTF-8");
  h.set("cache-control","no-store");
  h.set("x-vlm-worker-clean","no-auto-clean");
  h.set("referrer-policy","no-referrer");
  h.set("x-content-type-options","nosniff");
  h.set("permissions-policy","camera=(),microphone=(),geolocation=()");
  return h;
}

async function webLogin(req,env){
  try{
    const h=headersJson();

    if(req.method!=="POST"){
      clearCookies(h);
      return new Response(JSON.stringify({ok:false,message:"POST REQUIRED"}),{status:405,headers:h});
    }

    if(await rateLimited(env,req,"login"))return tooManyJson();

    let raw=await req.text();
    let data={};

    try{
      data=JSON.parse(raw||"{}")||{};
    }catch(_){
      data={key:raw};
    }

    const key=norm(data.key||"");

    if(!key){
      clearCookies(h);
      return new Response(JSON.stringify({ok:false,message:"ACCESS KEY REQUIRED"}),{status:400,headers:h});
    }

    const pf=await preflight(key,env);

    if(!pf||!pf.ok){
      clearCookies(h);
      return new Response(JSON.stringify({ok:false,message:(pf&&pf.message)||"LICENSE CHECK FAILED"}),{status:403,headers:h});
    }

    const session=pf.sessionToken||pf.token||pf.session||"";

    if(!session){
      clearCookies(h);
      return new Response(JSON.stringify({ok:false,message:"SESSION TOKEN MISSING"}),{status:500,headers:h});
    }

    saveCookies(h,key,session);

    return new Response(JSON.stringify({ok:true,message:"OK"}),{status:200,headers:h});
  }catch(e){
    const h=headersJson();
    clearCookies(h);
    return new Response(JSON.stringify({ok:false,message:"WEB LOGIN FAILED",error:String(e&&e.message?e.message:e)}),{status:500,headers:h});
  }
}

async function webActivate(req,env){
  try{
    if(await rateLimited(env,req,"activate"))return tooManyJson();
    if(!env||!env.LICENSE_API)return new Response(JSON.stringify({ok:false,message:"LICENSE BINDING MISSING"}),{status:500,headers:{"content-type":"application/json;charset=UTF-8","cache-control":"no-store","x-vlm-worker-clean":"no-auto-clean"}});
    const body=await req.text();
    const r=await env.LICENSE_API.fetch(new Request("https://license.internal/activate",{
      method:"POST",
      headers:{"content-type":"application/json"},
      body
    }));
    const txt=await r.text();
    return new Response(txt,{status:r.status,headers:{"content-type":"application/json;charset=UTF-8","cache-control":"no-store","x-vlm-worker-clean":"no-auto-clean"}});
  }catch(e){
    return new Response(JSON.stringify({ok:false,message:"WEB ACTIVATE FAILED",error:String(e&&e.message?e.message:e)}),{status:500,headers:{"content-type":"application/json;charset=UTF-8","cache-control":"no-store","x-vlm-worker-clean":"no-auto-clean"}});
  }
}

async function webVerify(req,env){
  try{
    if(await rateLimited(env,req,"verify"))return tooManyJson();
    if(!env||!env.LICENSE_API)return new Response(JSON.stringify({ok:false,message:"LICENSE BINDING MISSING"}),{status:500,headers:{"content-type":"application/json;charset=UTF-8","cache-control":"no-store","x-vlm-worker-clean":"no-auto-clean"}});
    const body=await req.text();
    const r=await env.LICENSE_API.fetch(new Request("https://license.internal/verify",{
      method:"POST",
      headers:{"content-type":"application/json"},
      body
    }));
    const txt=await r.text();
    return new Response(txt,{status:r.status,headers:{"content-type":"application/json;charset=UTF-8","cache-control":"no-store","x-vlm-worker-clean":"no-auto-clean"}});
  }catch(e){
    return new Response(JSON.stringify({ok:false,message:"WEB VERIFY FAILED",error:String(e&&e.message?e.message:e)}),{status:500,headers:{"content-type":"application/json;charset=UTF-8","cache-control":"no-store","x-vlm-worker-clean":"no-auto-clean"}});
  }
}

async function preflight(key,env){
  if(!env || !env.LICENSE_API)return {ok:false,message:"LICENSE BINDING MISSING"};
  const r=await env.LICENSE_API.fetch(new Request("https://license.internal/preflight",{
    method:"POST",
    headers:{"content-type":"application/json"},
    body:JSON.stringify({key})
  }));
  return await r.json().catch(()=>({ok:false,message:"LICENSE CHECK FAILED"}));
}

async function sessionCheck(token,env){
  if(!env || !env.LICENSE_API)return {ok:false,message:"LICENSE BINDING MISSING"};
  const r=await env.LICENSE_API.fetch(new Request("https://license.internal/session-check",{
    method:"POST",
    headers:{"content-type":"application/json"},
    body:JSON.stringify({token})
  }));
  return await r.json().catch(()=>({ok:false,message:"INVALID SESSION"}));
}

function reset(){
  const h=headersHtml();
  clearCookies(h);
  return panelResp(false,"",h);
}

async function panel(req,u){
  const saved=!!cookie(req,"vlm_key");
  const msg=u.searchParams.get("status")||"";
  return panelResp(saved,msg);
}

async function play(req,u,env){
  // Limita tentativas explícitas de key (anti brute-force). Reload por cookie não conta.
  if(u.searchParams.get("key") && await rateLimited(env,req,"play"))return tooManyHtml();

  const key=norm(u.searchParams.get("key")||cookie(req,"vlm_key"));
  let session=cookie(req,"vlm_session");

  if(!key){
    const h=headersHtml();
    clearCookies(h);
    return panelResp(false,"ACCESS KEY REQUIRED",h);
  }

  if(!session || u.searchParams.get("key")){
    const pf=await preflight(key,env);
    if(!pf.ok){
      const h=headersHtml();
      clearCookies(h);
      return panelResp(false,pf.message||"LICENSE CHECK FAILED",h);
    }
    session=pf.sessionToken;
  }else{
    const sc=await sessionCheck(session,env);
    if(!sc.ok){
      const pf=await preflight(key,env);
      if(!pf.ok){
        const h=headersHtml();
        clearCookies(h);
        return panelResp(false,pf.message||"LICENSE CHECK FAILED",h);
      }
      session=pf.sessionToken;
    }
  }

  const r=await fetch(ORIGIN,{headers:{"user-agent":req.headers.get("user-agent")||"Mozilla/5.0"}});
  let page=await r.text();
  page=page.replaceAll(ORIGIN,new URL(req.url).origin);
  page=injectPwa(page);

  const h=headersHtml();
  saveCookies(h,key,session);
  return new Response(page,{headers:h});
}

async function proxy(req,u,env){
  const key=norm(cookie(req,"vlm_key"));
  const session=cookie(req,"vlm_session");

  if(/\/assets\/script\/index\.[^/]+\.js$/i.test(u.pathname)){
    if(!key||!session){
      return new Response("location.href='/?status=ACCESS%20KEY%20REQUIRED';",{
        headers:{"content-type":"application/javascript;charset=UTF-8","cache-control":"no-store","x-vlm-worker-clean":"no-auto-clean"}
      });
    }

    const sc=await sessionCheck(session,env);
    if(!sc.ok){
      return new Response("location.href='/?status="+encodeURIComponent(sc.message||"INVALID SESSION")+"';",{
        headers:{"content-type":"application/javascript;charset=UTF-8","cache-control":"no-store","x-vlm-worker-clean":"no-auto-clean"}
      });
    }

    const js=await fetch(VL,{headers:{"cache-control":"no-cache"}}).then(r=>r.text());
    const payload={project:"ViciousLom",mode:"client",key:key,workerApi:LICENSE,gameUrl:ORIGIN,ts:Date.now()};
      const bridge=`;(()=>{try{window.VLM_APK_BRIDGE_PAYLOAD=${JSON.stringify(payload)};localStorage.setItem("vlm_apk_bridge_payload_v1",JSON.stringify(window.VLM_APK_BRIDGE_PAYLOAD));sessionStorage.setItem("vlm_apk_bridge_payload_v1",JSON.stringify(window.VLM_APK_BRIDGE_PAYLOAD))}catch(e){}})();`;
    return new Response(bridge+"\n"+js,{
      headers:{"content-type":"application/javascript;charset=UTF-8","cache-control":"no-store","x-vlm-worker-clean":"no-auto-clean"}
    });
  }

  const target=ORIGIN+u.pathname+u.search;
  const headers=new Headers(req.headers);
  headers.set("host",new URL(ORIGIN).host);

  const r=await fetch(target,{
    method:req.method,
    headers,
    body:(req.method==="GET"||req.method==="HEAD")?undefined:req.body,
    redirect:"follow"
  });

  const h=new Headers(r.headers);
  const loc=h.get("location");
  if(loc)h.set("location",loc.replaceAll(ORIGIN,new URL(req.url).origin));

  if((h.get("content-type")||"").includes("text/html")){
    let page=await r.text();
    page=page.replaceAll(ORIGIN,new URL(req.url).origin);
    page=injectPwa(page);
    return new Response(page,{status:r.status,headers:h});
  }

  return new Response(r.body,{status:r.status,headers:h});
}

function panelHtml(saved=false,msg=""){
  const input=saved?"":`<input id="k" placeholder="Enter your key" autocomplete="off">`;
  const btn=saved
    ? `<button onclick="location.href='/play'">CONTINUE PREMIUM</button><button class="ghost" onclick="location.href='/reset'">CHANGE KEY</button>`
    : `<button onclick="go()">START PREMIUM</button>`;
  const msgBox=msg?`<div class="msg">${msg}</div>`:"";

  return `<!doctype html><html lang="en"><head>${PWA_HEAD}<meta name="viewport" content="width=device-width,initial-scale=1"><title>ViciousLom</title><style>body{margin:0;background:radial-gradient(circle at top,#8b2cff,#160020 45%,#030006);font-family:Arial,Helvetica,sans-serif;color:white;min-height:100vh;display:flex;align-items:center;justify-content:center}.box{width:88%;max-width:430px;background:#10001d;border:1px solid #b45cff;border-radius:28px;padding:28px;box-shadow:0 0 35px #7c3cff;text-align:center}.m{font-size:58px}h1{font-size:40px;color:#efd6ff;text-shadow:0 0 15px #b45cff;margin:14px 0}p{color:#d8b4fe;font-size:18px}input,button{width:100%;box-sizing:border-box;padding:16px;border-radius:16px;font-size:17px;margin-top:14px}input{background:#130020;color:white;border:1px solid #b45cff;text-align:center}button{border:0;background:linear-gradient(90deg,#7c3cff,#d946ef);color:white;font-weight:900}.ghost{background:#21112f;border:1px solid #7c3cff}.msg{margin-top:14px;color:#ffb4f6;font-weight:900}</style></head><body><div class="box"><div class="m">🍄</div><h1>ViciousLom</h1><p>Premium Access</p>${input}${btn}${msgBox}</div><script>async function go(){let k=document.getElementById('k').value.trim();if(!k){location.href='/?status=ACCESS%20KEY%20REQUIRED';return}let b=document.querySelector('button');if(b){b.disabled=true;b.textContent='VALIDATING...'}try{let r=await fetch('/vlm-web-login',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({key:k})});let j=await r.json().catch(()=>({ok:false,message:'INVALID RESPONSE'}));if(j&&j.ok){location.href='/play';return}location.href='/?status='+encodeURIComponent((j&&j.message)||'ACCESS DENIED')}catch(e){location.href='/?status=CONNECTION%20FAILED'}}</script></body></html>`;
}


const __VLM_PWA_ICON_BASE64__ = "";
let __VLM_PWA_ICON_BYTES_CACHE__ = null;

function __vlmPwaIconBytes() {
  if (__VLM_PWA_ICON_BYTES_CACHE__) return __VLM_PWA_ICON_BYTES_CACHE__;
  const bin = atob(__VLM_PWA_ICON_BASE64__);
  const arr = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) arr[i] = bin.charCodeAt(i);
  __VLM_PWA_ICON_BYTES_CACHE__ = arr;
  return arr;
}

function __vlmPwaManifest() {
  return {
    "id": "/play",
    "name": "ViciousLom",
    "short_name": "ViciousLom",
    "description": "ViciousLom Web",
    "start_url": "/play",
    "scope": "/",
    "display": "fullscreen",
    "display_override": ["fullscreen", "standalone"],
    "orientation": "portrait",
    "background_color": "#050807",
    "theme_color": "#071f16",
    "icons": [
      {"src": "/icon.png?v=20260617_162830", "sizes": "1024x1024", "type": "image/png", "purpose": "any maskable"},
      {"src": "/icon-512.png?v=20260617_162830", "sizes": "512x512", "type": "image/png", "purpose": "any maskable"},
      {"src": "/icon-192.png?v=20260617_162830", "sizes": "192x192", "type": "image/png", "purpose": "any maskable"}
    ]
  };
}

function __vlmPwaSwJs() {
  return `
/* VLM_V7_PWA_RESTORE_SW */
self.addEventListener('install', event => {
  self.skipWaiting();
});
self.addEventListener('activate', event => {
  event.waitUntil(self.clients.claim());
});
self.addEventListener('fetch', event => {
  // no-op: não intercepta assets, não altera cache, não mexe no jogo
});
`;
}

async function __vlmPwaRestoreHtml(resp, req, u) {
  try {
    if (!resp || !(resp instanceof Response)) return resp;

    const path = String(u.pathname || "");
    const ct = String(resp.headers.get("content-type") || "");

    if (path !== "/" && path !== "/play" && !ct.includes("text/html")) return resp;

    let html = await resp.text();

    html = html
      .replace(/<link[^>]+rel=["']manifest["'][^>]*>\s*/gi, "")
      .replace(/<link[^>]+rel=["']apple-touch-icon["'][^>]*>\s*/gi, "")
      .replace(/<link[^>]+rel=["']icon["'][^>]*>\s*/gi, "")
      .replace(/<meta[^>]+name=["']theme-color["'][^>]*>\s*/gi, "")
      .replace(/<meta[^>]+name=["']mobile-web-app-capable["'][^>]*>\s*/gi, "")
      .replace(/<meta[^>]+name=["']apple-mobile-web-app-capable["'][^>]*>\s*/gi, "")
      .replace(/<meta[^>]+name=["']apple-mobile-web-app-title["'][^>]*>\s*/gi, "");

    const inject = `
<!-- VLM_V7_PWA_RESTORE -->
<link rel="manifest" href="/manifest.webmanifest?v=20260617_162830">
<link rel="icon" type="image/png" sizes="1024x1024" href="/icon.png?v=20260617_162830">
<link rel="apple-touch-icon" href="/icon.png?v=20260617_162830">
<meta name="theme-color" content="#071f16">
<meta name="mobile-web-app-capable" content="yes">
<meta name="apple-mobile-web-app-capable" content="yes">
<meta name="apple-mobile-web-app-title" content="ViciousLom">
<meta name="application-name" content="ViciousLom">
<script>
try {
  console.warn("[VLM_V7_PWA_RESTORE] installed");
  if ("serviceWorker" in navigator) {
    navigator.serviceWorker.register("/sw.js?v=20260617_162830", {scope:"/"})
      .then(function(){console.warn("[VLM_V7_PWA_RESTORE] sw registered")})
      .catch(function(e){console.warn("[VLM_V7_PWA_RESTORE] sw fail", e)});
  }
} catch(e) {}
</script>
`;

    let out = html;
    if (!out.includes("VLM_V7_PWA_RESTORE")) {
      if (/<head[^>]*>/i.test(out)) {
        out = out.replace(/<head[^>]*>/i, m => m + "\n" + inject);
      } else {
        out = inject + "\n" + out;
      }
    }

    const h = new Headers(resp.headers);
    h.set("content-type", "text/html; charset=utf-8");
    h.set("cache-control", "no-store");
    h.set("x-vlm-v7-pwa-restore", "1");
    h.delete("content-length");

    return new Response(out, {
      status: resp.status,
      statusText: resp.statusText,
      headers: h
    });
  } catch(e) {
    return resp;
  }
}

const __VLM_PWA_PREVIOUS_DEFAULT__ = {
  async fetch(req, env, ctx) {
    const u = new URL(req.url);

    if (req.method === "GET" && (u.pathname === "/manifest.webmanifest" || u.pathname === "/manifest.json")) {
      return new Response(JSON.stringify(__vlmPwaManifest(), null, 2), {
        headers: {
          "content-type": "application/manifest+json; charset=utf-8",
          "cache-control": "no-store",
          "x-vlm-v7-pwa-restore": "manifest"
        }
      });
    }

    if (req.method === "GET" && (
      u.pathname === "/icon.png" ||
      u.pathname === "/favicon.ico" ||
      u.pathname === "/icon-192.png" ||
      u.pathname === "/icon-512.png" ||
      u.pathname === "/icons/icon-192.png" ||
      u.pathname === "/icons/icon-512.png"
    )) {
      return new Response(__vlmPwaIconBytes(), {
        headers: {
          "content-type": "image/png",
          "cache-control": "public, max-age=86400",
          "x-vlm-v7-pwa-restore": "icon"
        }
      });
    }

    if (req.method === "GET" && u.pathname === "/sw.js") {
      return new Response(__vlmPwaSwJs(), {
        headers: {
          "content-type": "application/javascript; charset=utf-8",
          "cache-control": "no-store",
          "service-worker-allowed": "/",
          "x-vlm-v7-pwa-restore": "sw"
        }
      });
    }

    const resp = await __VLM_V7_ORIGINAL_DEFAULT__.fetch(req, env, ctx);
    return await __vlmPwaRestoreHtml(resp, req, u);
  }
};

