const __VLM_PWA_MANIFEST_FIX_JSON__ = '{\n  "id": "/play",\n  "name": "ViciousLom",\n  "short_name": "ViciousLom",\n  "description": "ViciousLom Web",\n  "start_url": "/play",\n  "scope": "/",\n  "display": "standalone",\n  "display_override": ["fullscreen", "standalone"],\n  "orientation": "portrait",\n  "background_color": "#050807",\n  "theme_color": "#071f16",\n  "prefer_related_applications": false,\n  "icons": [\n    {\n      "src": "/icon-192.png",\n      "sizes": "192x192",\n      "type": "image/png",\n      "purpose": "any maskable"\n    },\n    {\n      "src": "/icon-512.png",\n      "sizes": "512x512",\n      "type": "image/png",\n      "purpose": "any maskable"\n    },\n    {\n      "src": "/icon.png",\n      "sizes": "1024x1024",\n      "type": "image/png",\n      "purpose": "any maskable"\n    }\n  ]\n}';

export default {
  async fetch(req, env, ctx) {
    const u = new URL(req.url);

    if (req.method === "GET" && (
      u.pathname === "/manifest.webmanifest" ||
      u.pathname === "/manifest.json" ||
      u.pathname === "/site.webmanifest"
    )) {
      return new Response(__VLM_PWA_MANIFEST_FIX_JSON__, {
        headers: {
          "content-type": "application/manifest+json; charset=utf-8",
          "cache-control": "no-store, no-cache, must-revalidate, max-age=0",
          "access-control-allow-origin": "*",
          "x-vlm-v7-pwa-manifest-fix": "1"
        }
      });
    }

    return await __VLM_PWA_PREVIOUS_DEFAULT__.fetch(req, env, ctx);
  }
};

